#!/usr/bin/env node
// Generates the Claude Code and Codex plugins and their marketplace files from
// the hook table in src/runtime/host-hook-spec.ts, the same table the legacy
// `crosshead install claude-code|codex` writer uses.
//
//   node scripts/host-plugins.mjs          write the generated files
//   node scripts/host-plugins.mjs --check  fail if a checked-in file differs
//
// Uses the compiled spec in dist/ (run `npm run build` first). The plugins are
// thin: hooks, a setup skill and a launcher that runs the installed runtime.
// They never bundle, download or install runtime code.
import { chmodSync, existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import path from "node:path";

const require = createRequire(import.meta.url);
const root = path.resolve(path.dirname(new URL(import.meta.url).pathname), "..");

const json = (value) => `${JSON.stringify(value, null, 2)}\n`;

const author = { name: "FriendMachine", url: "https://crosshead.sh" };
const homepage = "https://crosshead.sh";
const repository = "https://github.com/FriendMachine/crosshead";
const description =
	"Persistent memory across coding agents. Hooks connect this host to the locally installed Crosshead runtime, shared with Claude Code, Codex, Hermes, OpenCode and Pi.";
const keywords = ["memory", "continuity", "hooks", "crosshead"];

const HOSTS = {
	"claude-code": {
		dir: "plugins/claude-code",
		label: "Claude Code",
		configFile: '${CLAUDE_CONFIG_DIR:-${CLAUDE_CODE_HOME:-$HOME/.claude}}/onlybots/claude-code-adapter.json',
		hookWrapper: "crosshead-claude-code-hook",
		doctorCheck: "claude_code_hooks",
		activate: "Start a new Claude Code session (or run /reload-plugins) so the hooks load with the runtime in place.",
		trust: null,
	},
	codex: {
		dir: "plugins/codex",
		label: "Codex",
		configFile: '${CODEX_HOME:-$HOME/.codex}/onlybots/codex-adapter.json',
		hookWrapper: "crosshead-codex-hook",
		doctorCheck: "codex_hooks",
		activate: "Start a new Codex session so the hooks load with the runtime in place.",
		trust:
			"Codex runs plugin hooks only after you trust them. Ask the user to open `/hooks`, review the Crosshead hooks and trust them. A changed plugin version needs a new review.",
	},
};

const shQuote = (value) => `'${value.replaceAll("'", `'"'"'`)}'`;

const noticeJson = (message) =>
	JSON.stringify({ systemMessage: message, hookSpecificOutput: { hookEventName: "SessionStart", additionalContext: message } });

const renderLauncher = (spec) => {
	const cases = Object.entries(HOSTS)
		.map(
			([host, info]) => `  ${host})
    hook=${info.hookWrapper}
    config="${info.configFile}"
    setup_notice=${shQuote(noticeJson(spec.pluginSetupHint(host)))}
    update_notice=${shQuote(noticeJson(spec.pluginUpdateHint(host)))}
    ;;`
		)
		.join("\n");
	return `#!/bin/sh
# Crosshead host plugin hook launcher. Generated by scripts/host-plugins.mjs from
# src/runtime/host-hook-spec.ts; do not edit.
#
# Runs the hook entrypoint of the Crosshead runtime installed by
# \`curl -fsSL https://crosshead.sh/install | bash\`. It never downloads or
# installs code. Without a configured runtime it prints a setup notice on
# SessionStart and exits 0 so the session is never blocked.
host="$1"
event="$2"
case "$host" in
${cases}
  *) exit 0 ;;
esac
home="\${CROSSHEAD_HOME:-\${CROSSHEAD_RUNTIME_HOME:-\${ONLYBOTS_HOME:-\${ONLYBOTS_RUNTIME_HOME:-}}}}"
if [ -z "$home" ]; then
  if [ ! -e "$HOME/.crosshead" ] && [ -d "$HOME/.onlybots" ]; then home="$HOME/.onlybots"; else home="$HOME/.crosshead"; fi
fi
wrapper="$home/bin/$hook"
if [ -x "$wrapper" ] && [ -f "$config" ] && grep -q '"hookMode"' "$config" 2>/dev/null; then
  exec "$wrapper" "$event" --home "$home" ${spec.PLUGIN_HOOK_VIA_FLAG.join(" ")}
fi
cat > /dev/null 2>&1 || true
if [ "$event" = SessionStart ]; then
  if [ -x "$wrapper" ] && [ -f "$config" ]; then
    printf '%s\\n' "$update_notice"
  else
    printf '%s\\n' "$setup_notice"
  fi
fi
exit 0
`;
};

const renderSetupSkill = (host) => {
	const info = HOSTS[host];
	return `---
name: setup
description: Install or update the Crosshead runtime and connect it to ${info.label}. Use when a Crosshead notice says it isn't set up or predates the plugin, or when the user asks to set up Crosshead memory.
---

# Set up Crosshead for ${info.label}

<!-- Generated by scripts/host-plugins.mjs; do not edit. -->

This plugin contains only hooks and this skill. The hooks run the Crosshead
runtime installed on this machine (\`~/.crosshead\` unless \`CROSSHEAD_HOME\` is
set). One runtime, daemon and identity is shared by Claude Code, Codex, Hermes,
OpenCode and Pi. Setup installs that runtime and connects it to ${info.label}.

Run each command with your shell tool. Use \`"\${CROSSHEAD_HOME:-$HOME/.crosshead}/bin/crosshead"\`
for \`crosshead\` if it is not on PATH.

1. Check the current state: \`crosshead doctor\`. If the runtime is installed and
   the \`${info.doctorCheck}\` check is ok with \`mode=plugin\`, setup is already
   done; report that and stop.
2. Explain the next two steps to the user and ask for explicit consent. Do not
   continue without a clear yes.
   - The installer is downloaded from https://crosshead.sh/install and run with
     bash. It downloads one release tarball, checks its SHA-256 against the
     digest pinned in the installer, installs three npm dependencies with install
     scripts disabled, and writes wrappers to \`~/.crosshead/bin\`. Runtimes
     never update themselves.
   - Quickstart creates a local identity if there is none (its private key stays
     in \`~/.crosshead\`), registers it with the hosted service at
     https://crosshead.sh and starts the local daemon. An existing identity is
     reused.
3. Install or update the runtime:

   \`\`\`sh
   curl -fsSL https://crosshead.sh/install | bash
   \`\`\`

4. Connect ${info.label}:

   \`\`\`sh
   crosshead quickstart --api-base https://crosshead.sh --adapter ${host} --workspace-root . --hook-mode plugin
   \`\`\`

   \`--hook-mode plugin\` keeps quickstart from writing its own ${info.label} hooks
   (this plugin provides them) and removes Crosshead hooks an earlier install
   wrote, so no event is captured twice.
5. Verify with \`crosshead doctor\`. Expect \`ok ${info.doctorCheck}: mode=plugin\`.
   Report any failed check to the user verbatim; do not work around it.
${info.trust ? `6. ${info.trust}\n7. ${info.activate}` : `6. ${info.activate}`}

Other hosts and scripts keep using \`curl -fsSL https://crosshead.sh/install | bash\`
followed by \`crosshead quickstart --adapter <host>\`. Remove Crosshead from
${info.label} by uninstalling this plugin; \`crosshead uninstall\` removes the runtime.
`;
};

/** Map of repository-relative path to file contents. `spec` is host-hook-spec. */
export const renderHostPluginFiles = (spec) => {
	const version = spec.CROSSHEAD_HOST_PLUGIN_VERSION;
	const name = spec.CROSSHEAD_PLUGIN_NAME;
	const launcher = renderLauncher(spec);
	const files = {
		".claude-plugin/marketplace.json": json({
			name: spec.CROSSHEAD_MARKETPLACE_NAME,
			owner: author,
			metadata: { description: "Crosshead plugins for Claude Code. Codex reads .agents/plugins/marketplace.json." },
			plugins: [{ name, source: `./${HOSTS["claude-code"].dir}`, description, version }],
		}),
		".agents/plugins/marketplace.json": json({
			name: spec.CROSSHEAD_MARKETPLACE_NAME,
			interface: { displayName: "Crosshead" },
			plugins: [
				{
					name,
					source: { source: "local", path: `./${HOSTS.codex.dir}` },
					policy: { installation: "AVAILABLE", authentication: "ON_INSTALL" },
					category: "Productivity",
				},
			],
		}),
		[`${HOSTS["claude-code"].dir}/.claude-plugin/plugin.json`]: json({
			name,
			displayName: "Crosshead",
			version,
			description,
			author,
			homepage,
			repository,
			license: "Apache-2.0",
			keywords,
		}),
		[`${HOSTS.codex.dir}/.codex-plugin/plugin.json`]: json({
			name,
			version,
			description,
			author,
			homepage,
			repository,
			license: "Apache-2.0",
			keywords,
			skills: "./skills/",
			hooks: "./hooks/hooks.json",
			interface: {
				displayName: "Crosshead",
				shortDescription: "Persistent memory shared across coding agents",
				developerName: "FriendMachine",
				category: "Productivity",
				capabilities: ["Read", "Write"],
				websiteURL: homepage,
			},
		}),
	};
	for (const host of Object.keys(HOSTS)) {
		const dir = HOSTS[host].dir;
		files[`${dir}/hooks/hooks.json`] = spec.renderPluginHooksFile(host);
		files[`${dir}/${spec.PLUGIN_HOOK_LAUNCHER}`] = launcher;
		files[`${dir}/skills/setup/SKILL.md`] = renderSetupSkill(host);
	}
	return files;
};

const isMain = process.argv[1] && path.resolve(process.argv[1]) === path.resolve(new URL(import.meta.url).pathname);
if (isMain) {
	const specPath = path.join(root, "dist", "runtime", "host-hook-spec.js");
	if (!existsSync(specPath)) {
		console.error("Missing dist/runtime/host-hook-spec.js; run npm run build first.");
		process.exit(1);
	}
	const spec = require(specPath);
	const files = renderHostPluginFiles(spec);
	const check = process.argv.includes("--check");
	const stale = [];
	for (const [relative, content] of Object.entries(files)) {
		const target = path.join(root, relative);
		const current = existsSync(target) ? readFileSync(target, "utf8") : null;
		if (current === content) continue;
		if (check) {
			stale.push(relative);
			continue;
		}
		mkdirSync(path.dirname(target), { recursive: true });
		writeFileSync(target, content);
		if (relative.endsWith(spec.PLUGIN_HOOK_LAUNCHER)) chmodSync(target, 0o755);
		console.log(`wrote ${relative}`);
	}
	if (stale.length > 0) {
		console.error(`Generated host plugin files are stale; run node scripts/host-plugins.mjs:\n${stale.join("\n")}`);
		process.exit(1);
	}
	if (check) console.log(`Host plugin files match the hook spec (${Object.keys(files).length} files).`);
}

